"use server";

/**
 * AI image *generation* action — text → new pixels via the Vercel AI
 * SDK image-model interface, with the generated bytes uploaded to the
 * Library bucket and a row inserted in `object`.
 */

import { generateImage } from "ai";
import imageSize from "image-size";
import { service_role } from "@/lib/supabase/server";
import { LibraryUpload } from "@/lib/library/upload.server";
import ai from "@/lib/ai";
import { computeImageCostMills } from "@/lib/ai/image-cost";
import {
  methods,
  withAiAuth,
  gridaProviderOptions,
  type AiActionResult,
} from "@/lib/ai/server";

export type GenerateAiImageInput = {
  prompt: string;
  width?: number;
  height?: number;
  aspect_ratio?: ai.image.AspectRatioString;
  /** Opt-in choice from the model card's declared quality options. */
  quality?: string;
  model: ai.image.ProviderModel | ai.image.ImageModelId;
  /** Verified org id — falls back to header / inferred via supabase auth. */
  organizationId?: number;
};

export type GenerateAiImageData = {
  object: {
    id: string;
    bytes: number;
    width: number;
    height: number;
    mimetype: string;
  };
  width: number;
  height: number;
  publicUrl: string;
  timestamp: string;
  modelId: string;
};

export type GenerateAiImageResponse = AiActionResult<GenerateAiImageData>;

export async function generateAiImage(
  input: GenerateAiImageInput
): Promise<GenerateAiImageResponse> {
  const model = methods.getSDKImageModel(input.model);
  if (!model) {
    return {
      success: false,
      code: "bad_request",
      message: "invalid model",
      status: 400,
    };
  }
  // This action's new quality input is metadata-backed. Unlike the legacy
  // hosted API, it never previously forwarded quality for older model cards.
  if (
    input.quality !== undefined &&
    !model.card.quality?.options.includes(input.quality)
  ) {
    return {
      success: false,
      code: "bad_request",
      message: "unsupported quality for this model",
      status: 400,
    };
  }

  return withAiAuth(
    "ai/image/generate",
    input.organizationId,
    async (organizationId) => {
      const costMills = computeImageCostMills(model.card, {
        n: 1,
        width: input.width,
        height: input.height,
        quality: input.quality,
      });

      const originProvider = model.card.id.split("/")[0]!;
      const generation = await generateImage({
        prompt: input.prompt,
        size:
          input.width && input.height
            ? `${input.width}x${input.height}`
            : undefined,
        aspectRatio: input.aspect_ratio,
        model: model.model,
        n: 1,
        providerOptions: {
          ...gridaProviderOptions({
            organizationId,
            feature: "ai/image/generate",
            costMills,
          }),
          ...(input.quality
            ? { [originProvider]: { quality: input.quality } }
            : {}),
        },
      });

      const meta = generation.responses[0];
      const { width, height } = imageSize(generation.image.uint8Array);
      const { object, publicUrl } = await LibraryUpload.generated(
        service_role.library,
        generation.image,
        {
          model: model.card.id,
          prompt: input.prompt,
          width,
          height,
        }
      );

      return {
        object,
        publicUrl,
        width,
        height,
        modelId: meta.modelId,
        timestamp: meta.timestamp.toISOString(),
      } satisfies GenerateAiImageData;
    }
  );
}
